head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldinf50100";
scwin._popupWindow = undefined;
scwin.dmenus = undefined;
scwin.idx = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — result, grnt_fee_procs_cd

/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "ul_81", attr: "__html", fn: function () { return ([String(dma_page.get("total")), String(dma_page.get("currentPage")), String(dma_page.get("pageCount"))].some(function (v) { return String(v === null ? '' : v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String(dma_page.get("total")) + "</strong>건 <span id=\"totPage1\">(" + String(dma_page.get("currentPage")) + "/" + String(dma_page.get("pageCount")) + ")</span>") : ''); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        const v = a.fn();
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_result", fn: function(){ return (!(String(((dma_pageContext.get("result") ?? "")) === null ? '' : ((dma_pageContext.get("result") ?? ""))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } },
        { childId: "__rb2", fn: function () { return String(String((dma_pageContext.get("totGrntFee") ?? ""))) + "원"; } },
        { childId: "__rb3", fn: function () { return String(String((dma_pageContext.get("prepayBal") ?? ""))) + "원"; } },
        { childId: "cal_stdCdGrntStartDd", fn: function () { return String(String((dma_pageContext.get("stdCdGrntStartDd") ?? ""))); } },
        { childId: "cal_stdCdGrntEndDd", fn: function () { return String(String((dma_pageContext.get("stdCdGrntEndDd") ?? ""))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntStartDd
 * @description 초기화 — datefmt cal std Cd Grnt Start Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stdCdGrntStartDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntStartDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_datefmt_cal_stdCdGrntEndDd
 * @description 초기화 — datefmt cal std Cd Grnt End Dd
 * @returns {void}
 * @hidden N
 */
scwin.init_datefmt_cal_stdCdGrntEndDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        const grnt_fee_procs_cd = (String(((dma_pageContext.get("grnt_fee_procs_cd") ?? "")) === null ? '' : ((dma_pageContext.get("grnt_fee_procs_cd") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("grnt_fee_procs_cd") ?? "")) === null ? '' : ((dma_pageContext.get("grnt_fee_procs_cd") ?? ""))));
        if (grnt_fee_procs_cd !== "") {
            $c.util.getComponent('slc_grntFeeProcsCd').setValue(grnt_fee_procs_cd);
        }
        const pageIndex = "" + dma_page.get("currentPage") + "";
        const pageObj = $('.paging td:contains(' + pageIndex + ')');
        const pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            const obj = pageObj[i];
            const val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            const font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf50100.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(fee vs srch) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":5
        ,"mmenu":2
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf50100' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_datefmt_cal_stdCdGrntStartDd();
        scwin.init_datefmt_cal_stdCdGrntEndDd();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldinf50100.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_prepay_onclick
 * @description btn_prepay 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_prepay_onclick = async function(e){
    try {
        await scwin.prepay()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf50100.btn_prepay_onclick' }); }
};

/**
 * @method
