};

/**
 * @method
 * @name btn_Download_onclick
 * @description btn_Download 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Download_onclick = async function(e){
    try {
        await scwin.download()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf50100.btn_Download_onclick' }); }
};

/**
 * @method
 * @name btn_search_onclick
 * @description btn_search 클릭 이벤트
 * @param {Object} e 이벤트 객체
