 */
scwin.btn_search_onclick = async function(e){
    try {
        await scwin.search()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf50100.btn_search_onclick' }); }
};

/**
 * @method
 * @name dataTb_oncellclick
 * @description dataTb 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["stdCdGrntFeeProcsStatCd"] !== '5' && r["stdCdGrntFeeProcsStatCd"] !== '9') { scwin.PopUp_FeeReport(r["stdCdApplId"]); return; } return; } await scwin.onPopupCode(r["mktCd"], r["stdCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_prepay
 * @description prepay 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_prepay = async function () {
    const sbmOptions = {
        id: "tx_fn_prepay",
        method: "post",
        action: "/fee/fee.do?method=prepayList",
        ref: "dma_prepayReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_search
 * @description search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search = async function () {
    const sbmOptions = {
        id: "tx_fn_search",
        method: "post",
        action: "/fee/fee.do?method=feeList",
        ref: "dma_searchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Download
 * @description Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Download = async function () {
    try { return await $c.data.downFile("/fee/fee.do?method=downGrntFeeInfoList", "", ($c.util.getComponent("dma_DownloadReq") ? $c.util.getComponent("dma_DownloadReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name tx_onPopupCode
 * @description on Popup Code 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_onPopupCode = async function () {
    const sbmOptions = {
        id: "tx_onPopupCode",
        method: "post",
        action: "/srch/srch.do?method=srchPopup",
        ref: "dma_onPopupCodeReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goPage
 * @description go Page 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goPage = async function () {
    const sbmOptions = {
        id: "tx_fn_goPage",
        method: "post",
        action: "/fee/fee.do?method=feeList",
        ref: "dma_goPageReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_PopUp_FeeReport
 * @description Pop Up Fee Report 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_PopUp_FeeReport = async function () {
    try { return await $c.data.downFile("/common/newPrint.do", "", ($c.util.getComponent("dma_PopUp_FeeReportReq") ? $c.util.getComponent("dma_PopUp_FeeReportReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name appDate2
 * @description 표준 API 조합으로 새로 작성한 검사 함수
 * @param {String} startId startId
 * @param {String} endId endId
 * @param {*} months months
 * @returns {void}
 * @hidden N
 */
scwin.appDate2 = function (startId, endId, months) { try { const end = $c.date.getServerDateTime(); const start = $c.date.addMonth(end, -Number(months || 0)); const r = function (nm) { return $c.util.getComponent('cal_' + nm) || $c.util.getComponent('ipt_' + nm) || $c.util.getComponent(String(nm)); }; const s = r(String(startId)); if (s && s.setValue) { s.setValue(start); } const e2 = r(String(endId)); if (e2 && e2.setValue) { e2.setValue(end); } } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'fn_appDate2' }); } };

/**
 * @method
 * @name dataTb_fillAct
 * @description data Tb fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dataTb_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            const v = '-';
            if (r) {  }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'dataTb.fillAct' });
    }
};

/**
 * @method
 * @name prepay
 * @description prepay 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.prepay = async function () {
    const width = 700;
    const height = 750;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/fee/fee.do?ipt_method=prepayList", unresolved: "nav:" + "/fee/fee.do?ipt_method=prepayList" }; })();
    let fm = (document.JLDINF50100 || { elements: [] });
    if (fm === null) {
        fm = (document.sideSearchForm || { elements: [] });
    }
    fm.action = "/fee/fee.do?method=prepayList";

};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    if ($c.str.getByteLength($c.util.getComponent('ipt_isurCd').getValue()) === 0) {
        await $c.win.alert("발행기관코드가 존재하지 않습니다.\n");
        return;
    }
    const frm = (document.JLDINF50100 || { elements: [] });
    if ($c.util.getComponent('cal_stdCdGrntStartDd').getValue()> $c.util.getComponent('cal_stdCdGrntEndDd').getValue()) {
        await $c.win.alert("코드부여  종료일이 시작일보다 이전날짜입니다.\n");
        $c.util.getComponent("cal_stdCdGrntEndDd").focus();
        return;
    }
    frm.action = "/fee/fee.do?method=feeList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
};

/**
 * @method
 * @name download
 * @description download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.download = async function () {
    await $c.win.alert("조회 내용이 없습니다.");
    return;
    await $c.win.alert("다운로드는 데이터에 따라 몇초에서 몇분가량 소요될 수 있습니다.");
    const frm = (document.JLDINF50100 || { elements: [] });
    frm.action = "/fee/fee.do?method=downGrntFeeInfoList";
    frm.method = "post";
    frm.target = "iframeExcel";
    await scwin.tx_fn_Download();
};

/**
 * @method
 * @name onPopupCode
 * @description on Popup Code 처리
 * @param {*} type type
 * @param {String} ipt_stdCd ipt_stdCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onPopupCode = async function (type, ipt_stdCd) {
    const fm = (document.popup_form || { elements: [] });
    const width = 1000;
    let height = 670;
    if (type === "01") {
        height = 700;
        scwin.idx = "3";
    } else {
        if (type === "02") {
            height = 660;
            scwin.idx = "2";
        } else {
            if (type === "03") {
                height = 620;
                scwin.idx = "4";
            } else {
                if (type === "04") {
                    height = 650;
                    scwin.idx = "5";
                } else {
                    if (type === "05") {
                        height = 650;
                        scwin.idx = "55";
                    } else {
                        if (type === "06") {
                            height = 660;
                            scwin.idx = "8";
                        } else {
                            if (type === "07") {
                                height = 720;
                                scwin.idx = "7";
                            } else {
                                if (type === "77") {
                                    height = 820;
                                    scwin.idx = "77";
                                } else {
