                                            height = 520;
                                            scwin.idx = "6";
                                        } else {
                                            if (type === "10") {
                                                height = 700;
                                                scwin.idx = "11";
                                            } else {
                                                if (type === "11") {
                                                    height = 720;
                                                    scwin.idx = "10";
                                                } else {
                                                    if (type === "12") {
                                                        height = 670;
                                                        scwin.idx = "14";
                                                    } else {
