                        }
                    }
                }
            }
        }
    }
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    scwin._popupWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/srch/srch.do?ipt_method=srchPopup", unresolved: "nav:" + "/srch/srch.do?ipt_method=srchPopup" }; })();
    $c.util.getComponent('ipt_stdcdType').setValue(scwin.idx);
    $c.util.getComponent('ipt_stdCd').setValue(ipt_stdCd);
    fm.action = "/srch/srch.do?method=srchPopup" + scwin.idx;

};

/**
 * @method
 * @name goPage
 * @description go Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goPage = async function () {
    const frm = (document.JLDINF50100 || { elements: [] });
    if ($c.util.getComponent('cal_stdCdGrntStartDd').getValue()> $c.util.getComponent('cal_stdCdGrntEndDd').getValue()) {
        await $c.win.alert("코드부여 종료일이 시작일보다 이전날짜입니다.\n");
        $c.util.getComponent("cal_stdCdGrntEndDd").focus();
        return;
    }
    frm.action = "/fee/fee.do?method=feeList";
    blockLoading();
    await scwin.tx_fn_goPage();
};

/**
 * @method
 * @name PopUp_FeeReport
 * @description Pop Up Fee Report 처리
 * @param {*} std_cd_appl_id std_cd_appl_id
 * @returns {void}
 * @hidden N
 */
scwin.PopUp_FeeReport = function (std_cd_appl_id) {
    $.ajax({ type: "POST", async: false, url: "/fee/fee.do?method=feeReportCommonAjax&std_cd_appl_id=" + std_cd_appl_id, data: {  }, success: async function(data) {
                const result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const form = (document.newReportForm || { elements: [] });
                for (key in result) {
                    if (form[camelize(key)]) {
                        form[camelize(key)].value = result[key];
                    }
                }
                $c.util.getComponent('dma_prepayReq').set('isurNm', result.com_nm);
                await scwin.tx_PopUp_FeeReport();
            }, error: async function(request, status, error) {
                await $c.win.alert("장애발생.");
                return;
            }, complete: function() {

            } });
};

